import {createEnergyFault,diagnosticSetup} from './energy-faults.mjs';
import {faultyEnergy} from './energy-faults.mjs';
import {mountEnergyDiagnostic} from './energy-diagnostic-ui.mjs';
import {mountEnergy3D} from './energy-3d.mjs';
import {calculate} from './models.mjs';
export function energyLearning(id,primary){
 if(!primary)return {update(){}};
 const root=document.createElement('section');root.className='energy-learning';primary.section.after(root);
 root.innerHTML='<h2>Predice, compara y explica</h2><p>Los dos bancos comparten tiempo; sus ajustes pueden ser distintos. Despiece y cámara son ayudas visuales, no cambian los cálculos.</p><button data-compare>Mostrar segundo banco</button><button data-predict>Reto de predicción</button><div class="prediction-box" hidden></div><div class="peer-controls" hidden></div><div class="peer-host" hidden></div>';
 const peerHost=root.querySelector('.peer-host'),pc=root.querySelector('.peer-controls'),question=root.querySelector('.prediction-box');let diagnostic=null,diagnosticState=null,sequencePrimary=null;let grid=null;let peer=null,current=null,open=false,score=0,attempts=0,answered=false;
 const cases={transformload:{a:1,b:48,title:'Relación 1 frente a 2, con 48 Ω',question:'Con 48 Ω, cambiamos Ns/Np de 1 a 2. ¿Qué pasa con la potencia?',choices:['Se cuadruplica','Se duplica','No cambia'],correct:0,explain:'Vs se duplica; Is también porque R permanece fija. P=Vs²/R pasa de 12 W a 48 W.',before:[1,48],after:[2,48]},opamp:{a:3,b:3,title:'Ganancia 3 frente a 5, con entrada de 3 V pico',question:'Con entrada de 3 V pico, subimos G de 3 a 5. ¿Qué ocurre en la cresta?',choices:['Salida de 15 V sin límite','Recorte a 12 V','La entrada se vuelve cero'],correct:1,explain:'La salida pedida es 15 V; los rieles de ±12 V la limitan. La alimentación aporta energía, pero no tensión ilimitada.',before:[3,3],after:[5,3]},relief:{a:4,b:60,title:'Carga 4 frente a 6,5 kN, ajuste 60 bar',question:'Subimos la carga de 4 a 6,5 kN con apertura a 60 bar y apertura total a 72 bar. ¿Qué ocurre?',choices:['Todo sigue igual','El cilindro se detiene inmediatamente','Parte del caudal vuelve al tanque y el cilindro va más lento'],correct:2,explain:'Se requieren 65 bar. Apertura=(65−60)/12=41,7 %. Retornan 2,5 L/min; el cilindro recibe 3,5 L/min y avanza a 0,0583 m/s.',before:[4,60],after:[6.5,60]}};
 const c=cases[id];pc.innerHTML='<h3>Banco B · '+c.title+'</h3><label>Primer parámetro B <input data-peer-a type="range"></label><label>Segundo parámetro B <input data-peer-b type="range"></label><p data-peer-values></p>';
 for(const k of ['a','b']){const source=document.querySelector('#'+k),input=pc.querySelector('[data-peer-'+k+']');for(const attr of ['min','max','step'])input.setAttribute(attr,source.getAttribute(attr));input.value=c[k];input.setAttribute('aria-label',document.querySelector('#l'+k).textContent+' del banco B');input.oninput=()=>update(current);}
 const toggle=root.querySelector('[data-compare]');toggle.onclick=()=>{open=!open;peerHost.hidden=pc.hidden=!open;toggle.textContent=open?'Ocultar segundo banco':'Mostrar segundo banco';toggle.setAttribute('aria-expanded',String(open));if(open&&!peer){peer=mountEnergy3D(id,{host:peerHost});peer.section.querySelector('.energy-heading span').textContent='BANCO B / MISMO RELOJ';document.dispatchEvent(new CustomEvent('energy-surface',{detail:peer.section.querySelector('.energy-viewport')}));}if(open){grid=document.createElement('div');grid.className='energy-pair';primary.section.before(grid);grid.append(primary.section,peerHost);}else if(grid){grid.before(primary.section);root.append(peerHost);grid.remove();grid=null;}update(current);};
 const command=(values,play=false)=>document.dispatchEvent(new CustomEvent('energy-command',{detail:{a:values[0],b:values[1],play}}));
 root.querySelector('[data-predict]').onclick=()=>{answered=false;question.hidden=false;command(c.before);question.replaceChildren();const title=document.createElement('p');title.textContent='PAUSA ANTES DEL CAMBIO · '+c.question;question.append(title);const feedback=document.createElement('p');feedback.setAttribute('role','status');for(const [i,label]of c.choices.entries()){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{if(answered)return;attempts++;if(i!==c.correct){feedback.textContent='Todavía no: relaciona el ajuste con el límite del modelo. Puedes volver a intentar.';return;}answered=true;score+=attempts===1?100:50;feedback.textContent=c.explain+' Puntuación de esta sesión: '+score+'.';question.querySelectorAll('button').forEach(x=>x.disabled=true);const run=document.createElement('button');run.textContent='Ver el cambio a 0,25×';run.onclick=()=>{command(c.after,true);if(!open)toggle.click();pc.querySelector('[data-peer-a]').value=c.before[0];pc.querySelector('[data-peer-b]').value=c.before[1];update(current);};question.append(run);};question.append(b);}question.append(feedback);attempts=0;};
 function update(m){if(!m)return;current=m;if(sequencePrimary)primary.update(faultyEnergy(sequencePrimary,m.a,m.b,m.t));if(open&&peer){const a=+pc.querySelector('[data-peer-a]').value,b=+pc.querySelector('[data-peer-b]').value;const other=diagnosticState?faultyEnergy(diagnosticState,m.a,m.b,m.t):calculate(id,id,a,b,m.t,m.on);peer.update(other);pc.querySelector('[data-peer-values]').textContent='Reloj compartido: '+m.t.toFixed(2)+' s · B: '+other.metrics.map(([name,n,u])=>name+' '+n.toFixed(2)+' '+u).join(' · ');}}
 function lock(active){for(const selector of ['#a','#b','[data-predict]','[data-compare]'])document.querySelector(selector).disabled=active;pc.hidden=active||!open;question.hidden=true;if(peer)peer.section.querySelector('.energy-heading span').textContent=active?'BANCO B / EN DIAGNÓSTICO':'BANCO B / MISMO RELOJ';}
 diagnostic=mountEnergyDiagnostic(root,id,{start:(s,values)=>{diagnosticState=s;command(values,true);if(!open)toggle.click();lock(true);update(current);},changed:()=>update(current),exit:()=>{diagnosticState=null;lock(false);update(current);}});
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||!e.data||e.data.type!=='energy-exam-case')return;const data=e.data;const allowed=cases[id];if(!allowed||!Array.isArray(data.faults))return;const s=createEnergyFault(id,()=>0,['basic','combined','intermittent'].includes(data.level)?data.level:'basic');if(!data.faults.every(f=>s.lab==='relief'?['pump','spring'].includes(f):s.lab==='opamp'?['gain','rail'].includes(f):['ratio','load'].includes(f)))return;s.faults=data.faults;s.repairedIds=Array.isArray(data.repairedIds)?[...new Set(data.repairedIds.filter(f=>s.faults.includes(f)))]:data.repaired?[...s.faults]:[];diagnosticState=s;sequencePrimary=Array.isArray(data.primaryRepairedIds)?{...s,repairedIds:[...new Set(data.primaryRepairedIds.filter(f=>s.faults.includes(f)))]}:null;command(diagnosticSetup[id],true);if(!open)toggle.click();lock(true);primary.section.querySelector('.energy-heading span').textContent=sequencePrimary?'BANCO A / TU SECUENCIA':'ANATOMY / BANCO A NORMAL';peer.section.querySelector('.energy-heading span').textContent=sequencePrimary?'BANCO B / RECOMENDADA':'BANCO B / EN DIAGNÓSTICO';document.querySelector('#metrics').hidden=!!sequencePrimary;document.querySelector('#metrics').style.display=sequencePrimary?'none':'';root.hidden=true;document.querySelector('.screen').hidden=true;document.querySelector('#challenge').hidden=true;document.querySelector('.observe').hidden=true;update(current);});
 if(new URLSearchParams(location.search).has('exam')){root.hidden=true;parent.postMessage({type:'energy-exam-ready'},location.origin);}
 return {update,debug:()=>({open,peer:peer?.debug(),score,answered,diagnostic:diagnostic?.state()})};
}
